INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷78·晋高祖纪·天福四年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00e77c12d50b6f8ea7c868872b15b90ddf01b8db/content/books/zizhi-tongjian/vol-282/year-0939/part-02/sources/library/jiuwudaishi-078-april/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年四月，段落 jiu-wudaishi-205deb4a7860-p001930；已核上下文及传主，纸本及异文待核。", "id": "4f41ade0-7b44-5e2d-b0bc-360553d9fb71"}, {"title": "旧五代史·卷78·晋高祖纪·天福四年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00e77c12d50b6f8ea7c868872b15b90ddf01b8db/content/books/zizhi-tongjian/vol-282/year-0939/part-02/sources/library/jiuwudaishi-078-may/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年五月，段落 jiu-wudaishi-205deb4a7860-p001931；已核上下文及传主，纸本及异文待核。", "id": "1743fac9-7061-551a-ad91-2bcb532c384f"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00e77c12d50b6f8ea7c868872b15b90ddf01b8db/content/books/zizhi-tongjian/vol-282/year-0939/part-02/sources/library/tongjian-282-939-spring-summer/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003349；电子底本待考，分段待核", "id": "78a64ddf-01ce-59c9-8104-c62aada229dd"}, {"title": "新五代史·卷68·闽世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00e77c12d50b6f8ea7c868872b15b90ddf01b8db/content/books/zizhi-tongjian/vol-282/year-0939/part-02/sources/library/xinwudaishi-068-min-superstition/source.txt", "note": "《新五代史》卷68·闽世家，段落 xin-wudaishi-b08f244b9241-p003404；已核上下文及传主，纸本及异文待核。", "id": "f896e847-4ff3-5e8e-8ce1-81cc59f80548"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/tongjian-282-939-opening/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003348；电子底本待考，分段待核", "id": "83432c9e-3ed6-5bee-a017-a2396a6d9ba8"}, {"title": "旧五代史·卷78·晋高祖纪·天福四年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0ce37b98c182cdb5c5cd2ee909baa3b407a4785/content/books/zizhi-tongjian/vol-282/year-0939/part-01/sources/library/jiuwudaishi-078-march/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年三月，段落 jiu-wudaishi-205deb4a7860-p001929；已核上下文及传主，纸本及异文待核。", "id": "376eaf5e-c2ae-5d4f-8723-cdac07ca5ecc"}]'::jsonb)
