INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王彦忠（怀远城戍将）", "aliases": ["王彦忠", "王彥忠"], "era": "五代十国", "birth_year": null, "death_year": 939, "description": "939年据怀远城叛乱，接受后晋供奉官齐延祚招谕后投降，却被齐延祚擅自杀死。《旧五代史》记其为灵州戍将；《资治通鉴》电子本此处作寻州。生年未载。", "biography": null, "status": "draft", "id": "ff667f62-1d43-5880-9f39-89d047913db0"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "齐延祚", "aliases": ["齊延祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋供奉官。939年奉命招谕怀远城叛将王彦忠，招降后擅自将他杀死，被石敬瑭除名、杖打并流放。生卒年未载。", "biography": null, "status": "draft", "id": "d126cf06-992a-5948-8e76-9754a191d4e5"}, {"name": "仁美（回鹘奉化可汗）", "aliases": ["仁美（回鹘可汗）", "奉化可汗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "回鹘可汗。939年三月被后晋册为奉化可汗。个人姓氏及生卒年本次未核。", "biography": null, "status": "draft", "id": "c2b83196-a4b6-5769-8205-f332fa07a631"}, {"name": "徐知证", "aliases": ["徐知證"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐氏宗室。937年十月，徐诰即位后封他为江王。《新五代史》也记载这一封爵。", "biography": null, "status": "draft", "id": "4343d028-faf4-51b1-a2ef-c11390e12a40"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "刘处让", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘处让。", "biography": null, "status": "draft", "id": "7607f037-c9b6-5f79-b064-81fcfd4ee40d"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "司徒诩", "aliases": ["司徒詡"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：司徒诩，病告半年者。", "biography": null, "status": "draft", "id": "656dbdcb-bb8b-591c-8b1d-df97e69cded9"}, {"name": "颜衎", "aliases": ["顏衎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋枢密直学士、工部郎中。939年废枢密院后，解除院内职务，保留本官。生卒年未载。", "biography": null, "status": "draft", "id": "b9f8cc2c-05c1-565a-a870-6fcd731c4ba9"}, {"name": "李专美", "aliases": ["李專美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李专美，夜直、被责问者。", "biography": null, "status": "draft", "id": "845c43a9-912b-516b-bc61-71674907ccfa"}, {"name": "韩昭胤", "aliases": ["韓昭胤", "韩昭裔", "韓昭裔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩昭胤，原凤翔节度判官、获谏议大夫及端明学士者。", "biography": null, "status": "draft", "id": "9db1ff26-850f-505f-a52b-af3e50eb139a"}, {"name": "马胤孙", "aliases": ["馬胤孫", "马裔孙", "馬裔孫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马胤孙，观察判官、劝遵君命者。", "biography": null, "status": "draft", "id": "8d6b60ab-f30f-5e4d-b55d-60225289b374"}, {"name": "房暠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：房暠，宣徽北院使获任者。", "biography": null, "status": "draft", "id": "6154e92b-6df3-589f-8727-8684553681bc"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "林兴（闽国巫者）", "aliases": ["林兴", "林興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国巫者，受王继鹏信任，假托宝皇之命参与政事。939年诬指王延武、王延望谋变，并奉命将二人及其五名子女杀死；同年因骗局败露被流放泉州。《新五代史》另记他后来被杀，具体时间未载。", "biography": null, "status": "draft", "id": "fb411814-4b89-58fe-b422-59b8082ab234"}, {"name": "王延武", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 939, "description": "曾任建州刺史。《资治通鉴》称他为王继鹏的叔父，《新五代史》记他为王审知之子。939年王继鹏听信林兴的谎言，命人将他杀死。生年未载。", "biography": null, "status": "draft", "id": "c8e85a41-fc1f-56d6-a8fe-29611e626319"}, {"name": "王延望", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 939, "description": "闽国户部尚书。《资治通鉴》称他为王继鹏的叔父，《新五代史》记他为王审知之子。939年王继鹏听信林兴的谎言，命人将他杀死。生年未载。", "biography": null, "status": "draft", "id": "677fba15-f8a6-5849-ae55-c61019e58041"}, {"name": "王审知", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受授者。", "biography": null, "status": "draft", "id": "099c16ed-15be-506b-a65f-aa94c272cbd8"}, {"name": "陈守元", "aliases": ["陳守元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈守元，道士、劝建宫者。", "biography": null, "status": "draft", "id": "5df7e840-5673-57f7-83d7-ba3228fe2d3c"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "徐知谔", "aliases": ["徐知諤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐知谔，润州团练使、被叙亲自交易者。", "biography": null, "status": "draft", "id": "ac076e03-0802-5e0f-9c3f-c1a717712543"}, {"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "杨珙", "aliases": ["楊珙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：杨珙，获封建安王者。", "biography": null, "status": "draft", "id": "36891e7d-cbab-5a6a-87ef-52ca0cefa3a5"}, {"name": "杨琏", "aliases": ["楊璉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：杨琏，获封江都王者。", "biography": null, "status": "draft", "id": "4975dc84-c87f-5d7f-b1e7-3254e45440ea"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "王继严", "aliases": ["王繼嚴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继严，建王、权判六军诸卫获任者。", "biography": null, "status": "draft", "id": "d482c47e-008e-5701-bfc0-af64dfe325d7"}, {"name": "王继镛", "aliases": ["王繼鏞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王继鹏的弟弟。939年六月，王继严被解除兵权后，王继镛受命判六军，职名不再包含诸卫二字。生卒年未载。", "biography": null, "status": "draft", "id": "64714ddd-3d15-5c12-a4af-c0f50c4b6b0d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王彦忠据怀远城叛乱", "start_year": 939, "end_year": 939, "time_original": "939年三月，具体日期未载", "dynasty": "五代十国", "description": "戍将王彦忠据怀远城叛乱。《旧五代史》记为灵州戍将；《资治通鉴》所用电子本此处作“寻州”，地名字形差异保留。", "phases": [], "location_name": "灵州、怀远城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1a431227-8396-5429-97cb-650ff0a627ce"}, {"title": "石敬瑭派齐延祚招谕王彦忠，王彦忠投降", "start_year": 939, "end_year": 939, "time_original": "939年三月，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭派齐延祚招谕王彦忠，王彦忠投降。", "phases": [], "location_name": "怀远城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "34b5e165-59ab-5513-b043-84d789a8d824"}, {"title": "齐延祚擅自杀死已投降的王彦忠", "start_year": 939, "end_year": 939, "time_original": "939年三月，具体日期未载", "dynasty": "五代十国", "description": "齐延祚擅自杀死已投降的王彦忠。", "phases": [], "location_name": "怀远城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "70bc9bb6-a2bc-54af-8b38-7099630514ab"}, {"title": "石敬瑭因齐延祚擅杀降将，将其除名、杖打并流放", "start_year": 939, "end_year": 939, "time_original": "939年三月，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭发怒，强调自己即位以来没有失信于人，王彦忠已经交出武器并出迎，齐延祚无权擅杀。石敬瑭将齐延祚除名、重杖并流放。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "47195440-b040-5a27-8408-439e1012c1a6"}, {"title": "史书记述有人认为齐延祚杀降不应免死", "start_year":