year": null, "end_year": null, "time_original": "梁太祖以来的制度追述，非939年单日事件", "dynasty": "五代十国", "description": "《资治通鉴》概述，梁太祖以来，军国大事多由皇帝与崇政使、枢密使商议；宰相接受决定，负责诏令、典故和文书事务。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "593120c4-95ff-5921-9b2e-19cebde3d37d"}, {"title": "史书解释石敬瑭起初限制枢密使权力的原因", "start_year": null, "end_year": null, "time_original": "石敬瑭即位之初的追述，本句未列具体日期", "dynasty": "五代十国", "description": "《资治通鉴》解释，石敬瑭顾忌后唐明宗时期安重诲专横的旧事，因此即位初只让桑维翰兼任枢密使。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c2278e83-0858-5bae-9aae-d0a7dd3d853c"}, {"title": "刘处让任枢密使后奏对不合旨意，随后因母丧服丧", "start_year": null, "end_year": null, "time_original": "废枢密院之前的追述，母丧具体日期未载", "dynasty": "五代十国", "description": "刘处让接任枢密使后，奏对多次不合石敬瑭的心意，随后因母亲去世服丧。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "651b5861-0441-5133-a950-14b18e6a5f8a"}, {"title": "石敬瑭废枢密院，将印信和事务交中书、宰相分管", "start_year": 939, "end_year": 939, "time_original": "939年四月甲申", "dynasty": "五代十国", "description": "石敬瑭废除枢密院，将院印交给中书，原由枢密院处理的事务改由宰相分别管理。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "15ece2b6-72f4-5f51-aa34-e0178c0a8a18"}, {"title": "张从恩由枢密副使改任宣徽使", "start_year": 939, "end_year": 939, "time_original": "939年四月甲申", "dynasty": "五代十国", "description": "张从恩由枢密副使改任宣徽使。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6a555696-0354-54ad-8b69-b42254e2ecfd"}, {"title": "司徒诩和颜衎解除枢密院职务，保留本官", "start_year": 939, "end_year": 939, "time_original": "939年四月甲申", "dynasty": "五代十国", "description": "司徒诩和颜衎解除枢密院职务，保留本官。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3c714a10-190c-52df-9335-3d24202ea64b"}, {"title": "史书记述勋臣和近臣仍希望恢复枢密院", "start_year": null, "end_year": null, "time_original": "废枢密院之后的持续追述，具体起止年月未载", "dynasty": "五代十国", "description": "《资治通鉴》评价部分勋臣和近臣不明大体、习惯旧制，仍经常希望恢复枢密院。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "96020293-d6a1-5380-894e-109d783c165e"}, {"title": "石敬瑭因前朝旧臣贫困，任李专美为赞善大夫", "start_year": 939, "end_year": 939, "time_original": "939年四月后续条下，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭看到两京被除名的后唐旧臣生活贫困憔悴，重新任李专美为赞善大夫。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5dc6ac5f-6680-54fb-a818-1c375b695701"}, {"title": "韩昭胤、马胤孙和房暠获授官职并退休", "start_year": 939, "end_year": 939, "time_original": "939年四月丙戌", "dynasty": "五代十国", "description": "韩昭胤、马胤孙和房暠获授官职并退休。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bb86a5f5-ff78-53fb-80f7-d6dbc894be7f"}, {"title": "林兴因与王延武有怨，假托神言诬指两位王氏宗室谋变", "start_year": 939, "end_year": 939, "time_original": "939年四月后续条下，具体日期未载", "dynasty": "五代十国", "description": "王继鹏忌惮叔父王延武和王延望的才名。巫者林兴与王延武有怨，假托鬼神之言，